"""Türkçe — peygamberler (prophets_001 … prophets_150)."""

T = {
"prophets_001": ("Hangi peygamber Allah'ın emriyle gemiyi inşa etti?", ["Nuh", "İbrahim", "Musa", "Yusuf"], "Allah, müminleri tufandan kurtarmak için Nuh'a gemiyi inşa etmesini emretti."),
"prophets_002": ("Hangi peygamber, Allah'ın kendisi için serin ve güvenli kıldığı bir ateşe atıldı?", ["İbrahim", "Nuh", "Davud", "Eyyub"], "Allah ateşe, İbrahim için serin ve güvenli olmasını emretti."),
"prophets_003": ("Hangi peygamberi kocaman bir balık yuttu?", ["Yunus", "İlyas", "İdris", "Zekeriya"], "Yunus, kavmini öfkeyle terk ettikten sonra balık tarafından yutuldu; Allah onu bağışladı."),
"prophets_004": ("Hangi peygamber hükümdarın yedi semiz ve yedi zayıf inek rüyasını yorumladı?", ["Yusuf", "Yakub", "İsmail", "İshak"], "Yusuf hükümdarın rüyasını yorumladı: yedi bolluk yılının ardından yedi kıtlık yılı."),
"prophets_005": ("Kur'an'a göre Allah hangi peygamberle doğrudan konuştu?", ["Musa", "Harun", "Yusuf", "Süleyman"], "Kur'an, Allah'ın Musa ile doğrudan konuştuğunu bildirir."),
"prophets_006": ("Hangi peygamber kuşların dilini anlayabiliyordu?", ["Süleyman", "Davud", "Yunus", "Yusuf"], "Allah Süleyman'a kuşların dilini öğretti."),
"prophets_007": ("Zebur adlı kitap hangi peygambere verildi?", ["Davud", "Musa", "İsa", "İbrahim"], "Kur'an, Zebur'un Davud'a verildiğini bildirir."),
"prophets_008": ("Hangi peygamber Allah'ın «Ol» emriyle babasız olarak doğdu?", ["İsa", "Yahya", "İsmail", "İshak"], "Kur'an, İsa'nın yalnızca Allah'ın sözüyle, babasız mucizevi doğumunu anlatır."),
"prophets_009": ("Kur'an'ın hangi suresi bir peygamberin annesinin adını taşır?", ["Meryem", "Yusuf", "Nuh", "Hud"], "19. sure Meryem, İsa peygamberin annesinin adını taşır."),
"prophets_010": ("Hangi peygamber ağır bir hastalıkla sınandı ve sabrıyla övüldü?", ["Eyyub", "Zekeriya", "Yahya", "İdris"], "Eyyub çok zor bir imtihanda sabretti ve Allah onu mükâfatlandırdı."),
"prophets_011": ("Allah meleklere, bir şeref nişanesi olarak kimin önünde secde etmelerini emretti?", ["Âdem", "Nuh", "İbrahim", "Musa"], "Allah meleklere, ibadet değil şeref nişanesi olarak Âdem'e secde etmelerini emretti."),
"prophets_012": ("Hangi peygamber «Halilullah», Allah'ın yakın dostu olarak anılır?", ["İbrahim", "Musa", "İsa", "Muhammed ﷺ"], "Kur'an, İbrahim'i Allah'ın yakın dostu (halil) olarak niteler."),
"prophets_013": ("Hangi peygamberi kardeşleri kuyuya attı?", ["Yusuf", "Bünyamin", "Yakub", "İsmail"], "Yusuf'un kardeşleri onu kıskançlıktan kuyuya attılar."),
"prophets_014": ("Hangi peygamberin kavmi onu reddettikten sonra tufanla helak edildi?", ["Nuh", "Hud", "Salih", "Şuayb"], "Nuh'un kavmi, mesajını ısrarla reddettikten sonra tufanla yutuldu."),
"prophets_015": ("Hangi peygamber, kavmini Firavun'dan kurtarmak için denizin yarıldığını gördü?", ["Musa", "Harun", "Yusuf", "İsmail"], "Allah Musa'ya denize vurmasını emretti; deniz yarıldı ve müminler geçti."),
"prophets_016": ("Hangi peygamber, babası Davud ile birlikte koyunların otladığı bir tarla davasında hüküm verdi?", ["Süleyman", "İsmail", "Yusuf", "İshak"], "Kur'an, Süleyman ve Davud'un bu davada hüküm verdiğini ve Allah'ın Süleyman'a bunun anlayışını verdiğini anlatır."),
"prophets_017": ("Kimin annesine bebeğini nehre bırakması bildirildi?", ["Musa", "İsa", "Yusuf", "İsmail"], "Allah, Musa'nın annesine onu korumak için bir sandık içinde nehre bırakmasını ilham etti."),
"prophets_018": ("Kimin dişi devesi kavmi Semud'a bir mucize olarak verildi?", ["Salih", "Hud", "Şuayb", "Lut"], "Allah, Semud kavmine Salih peygamber aracılığıyla bir dişi deve mucizesi gönderdi."),
"prophets_019": ("Allah hangi peygambere bütün varlıkların isimlerini öğretti?", ["Âdem", "Nuh", "İbrahim", "Musa"], "Allah Âdem'e bütün isimleri öğretti ve melekler Allah'ın hikmetini kabul ettiler."),
"prophets_020": ("Hangi peygamber henüz beşikte bir bebekken insanlarla konuştu?", ["İsa", "Yahya", "Yusuf", "İsmail"], "Bebek İsa beşikten konuştu: «Ben Allah'ın kuluyum; O bana Kitab'ı verdi.»"),
"prophets_021": ("İbrahim, Kâbe'nin temellerini hangi oğluyla yükseltti?", ["İsmail", "İshak", "Yakub", "Yusuf"], "«İbrahim ve İsmail Beyt'in temellerini yükseltirken…»: birlikte inşa ettiler."),
"prophets_022": ("Zekeriya peygambere yaşlılığında hangi oğul müjdelendi?", ["Yahya", "İsa", "İsmail", "İshak"], "«Ey Zekeriya, sana adı Yahya olan bir oğul müjdeliyoruz.»"),
"prophets_023": ("Allah Musa'ya asasını atmasını söylediğinde asa neye dönüştü?", ["Hareket eden bir yılana", "Bir kuşa", "Bir su kaynağına", "Bir ışığa"], "«At onu ey Musa!» Attı, hızla hareket eden bir yılan oluverdi."),
"prophets_024": ("Genç Yusuf rüyasında kendisine secde eden neyi gördü?", ["On bir yıldız, güneş ve ay", "Yedi semiz inek", "Altın yağmuru", "Hurma bahçesi"], "Yusuf, on bir yıldızın, güneşin ve ayın kendisine secde ettiğini gördü: kaderinin bir işareti."),
"prophets_025": ("Hud peygamber hangi kavme gönderildi?", ["Âd kavmine", "Semud kavmine", "Medyen halkına", "Firavun'un kavmine"], "«Âd'a da kardeşleri Hud'u…»: onları yalnızca Allah'a ibadete çağırdı."),
"prophets_026": ("Şuayb peygamber hangi kavme gönderildi?", ["Medyen halkına", "Âd kavmine", "Semud kavmine", "Nuh'un kavmine"], "«Medyen'e de kardeşleri Şuayb'ı…»: ölçü ve tartıyı adaletle yapmalarını emretti."),
"prophets_027": ("Kur'an'da «Zünnun» (balık sahibi) olarak anılan peygamber kimdir?", ["Yunus", "Musa", "Süleyman", "Eyyub"], "«Zünnun'u da an, hani öfkeyle gitmişti…»: bu, sonra balık tarafından yutulan Yunus'tur."),
"prophets_028": ("Musa, Allah'ın kendisine özel bir ilim verdiği bir kuldan öğrenmek için hangi surede yolculuk eder?", ["Kehf", "Yusuf", "Meryem", "Neml"], "Kehf suresinde Musa, ilim sahibi bir kula eşlik eder ve henüz anlamadığı şeylere sabretmeyi öğrenir."),
"prophets_029": ("Kur'an'da adı en çok geçen peygamber kimdir?", ["Musa", "İbrahim", "Nuh", "İsa"], "Musa, Kur'an'da adı en çok anılan peygamberdir; Firavun'la kıssası defalarca tekrarlanır."),
"prophets_030": ("Kur'an'da kaç peygamberin adı geçer?", ["25", "10", "50", "99"], "Âdem'den Muhammed ﷺ'e kadar Kur'an'da yirmi beş peygamberin adı geçer."),
"prophets_031": ("Allah'ın izniyle hangi peygamber körü ve alacalıyı iyileştirdi?", ["İsa", "Musa", "Davud", "Yunus"], "İsa, Allah'ın izniyle körü ve alacalıyı iyileştirdi: kavmi için bir mucize."),
"prophets_032": ("Kur'an'a göre Nuh, kavmini Allah'a çağırarak aralarında ne kadar kaldı?", ["950 yıl", "100 yıl", "300 yıl", "40 yıl"], "«Aralarında bin yıldan elli yıl eksik kaldı»: 950 yıl sabırlı bir davet."),
"prophets_033": ("Kur'an'a göre Allah Âdem'i neyden yarattı?", ["Çamurdan", "Nurdan", "Ateşten", "Sudan"], "Allah meleklere şöyle dedi: «Ben çamurdan bir insan yaratacağım.»"),
"prophets_034": ("Âdem ile eşini yasak ağaçtan yemeye kim kandırdı?", ["Şeytan (İblis)", "Bir melek", "Bir kuş", "Bir kral"], "Şeytan, Allah'ın yasakladığı ağaçtan yemeleri için onlara vesvese verdi."),
"prophets_035": ("İblis, Âdem'e secde etmeyi reddetmesine hangi gerekçeyi gösterdi?", ["«Ben ondan üstünüm: beni ateşten, onu çamurdan yarattın»", "Âdem'in kim olduğunu bilmiyordu", "Meleklerden korkuyordu", "Uyuyordu"], "İblis kibirle reddetti: «Beni ateşten yarattın, onu ise çamurdan yarattın.»"),
"prophets_036": ("Âdem'in iki oğlu arasındaki cinayetten sonra Allah, cesedin nasıl gömüleceğini göstermek için hangi hayvanı gönderdi?", ["Bir karga", "Bir köpek", "Bir güvercin", "Bir tilki"], "Allah, katile kardeşinin cesedini nasıl gizleyeceğini göstermek için toprağı eşeleyen bir karga gönderdi."),
"prophets_037": ("Kur'an İdris peygamber hakkında ne söyler?", ["Allah onu yüce bir makama yükseltti", "Bir gemi yaptı", "Bir balık tarafından yutuldu", "Karıncalarla konuştu"], "«Ve onu yüce bir makama yükselttik.»"),
"prophets_038": ("Nuh'un oğlu, babası onu gemiye çağırdığında ne yaptı?", ["Reddetti ve bir dağa sığınacağını söyledi", "İlk o bindi", "Kendi gemisini yaptı", "Hayvan toplamaya gitti"], "«Bir dağa sığınacağım» dedi; dalgalar onu yuttu."),
"prophets_039": ("Kur'an'a göre Nuh'un gemisi hangi dağa oturdu?", ["Cudi dağına", "Sina dağına", "Uhud dağına", "Arafat dağına"], "«Ve gemi Cudi'ye oturdu.»"),
"prophets_040": ("Allah Nuh'a gemiye ne yüklemesini emretti?", ["Her türden bir çift ve müminleri", "Yalnızca ailesini", "Yalnızca kuşları", "Altın ve gümüş"], "«Her türden bir çifti, aileni… ve iman edenleri ona yükle.»"),
"prophets_041": ("Nuh'un kavminin ileri gelenleri onu gemi yaparken görünce ne yaptılar?", ["Onunla alay ettiler", "Ona yardım ettiler", "Ona odun getirdiler", "Onunla dua ettiler"], "Kavminin ileri gelenleri yanından her geçtiklerinde onunla alay ediyorlardı."),
"prophets_042": ("Kur'an İsra suresinde Nuh'u nasıl niteler?", ["Çok şükreden bir kul", "Güçlü bir kral", "Büyük bir gezgin", "Sessiz bir adam"], "«Şüphesiz o, çok şükreden bir kuldu.»"),
"prophets_043": ("Hud'un gönderildiği Âd kavmi nasıl helak edildi?", ["Şiddetli, uğultulu bir rüzgârla", "Tufanla", "Taş yağmuruyla", "Depremle"], "«Âd'a gelince, onlar uğultulu, şiddetli bir rüzgârla helak edildiler.»"),
"prophets_044": ("Salih'in kavmi Semud'u ne yakaladı?", ["Korkunç bir çığlık", "Tufan", "Kıtlık", "Çekirge sürüsü"], "«Zulmedenleri o korkunç çığlık yakaladı.»"),
"prophets_045": ("Kur'an'da geçen İbrahim'in babasının adı nedir?", ["Âzer", "Tarih", "Lut", "Kenan"], "«İbrahim babası Âzer'e demişti ki: putları tanrı mı ediniyorsun?»"),
"prophets_046": ("İbrahim putları kırdıktan sonra hangisini sağlam bıraktı?", ["En büyüğünü", "En küçüğünü", "Altın olanı", "Hiçbirini, hepsini kırdı"], "Kavmi ona sorsun diye en büyüğü hariç hepsini paramparça etti."),
"prophets_047": ("İbrahim yıldızın, ayın ve sonra güneşin battığını görünce ne dedi?", ["«Ben batanları sevmem»", "«Güneş benim rabbimdir»", "«Ay en güzelidir»", "«Uyuyacağım»"], "Her biri batınca «Ben batanları sevmem» dedi ve Yaratıcı'ya yöneldi."),
"prophets_048": ("Allah, ölüleri nasıl dirilttiğini göstermek için İbrahim'e kaç kuş almasını söyledi?", ["Dört", "İki", "Yedi", "On iki"], "«Dört kuş al… sonra onları çağır: koşarak sana gelecekler.»"),
"prophets_049": ("İbrahim, müjdeyle gelen melek misafirlerine ne ikram etti?", ["Kızarmış bir buzağı", "Hurma", "Süt", "Ekmek ve bal"], "«Çok geçmeden kızarmış bir buzağı getirdi.»"),
"prophets_050": ("Melekler İbrahim'in eşine hangi müjdeyi getirdiler?", ["İshak'ın doğumunu", "Bir yolculuğu", "Büyük bir serveti", "Bol yağmuru"], "«Ona İshak'ı, İshak'ın ardından da Yakub'u müjdeledik.»"),
"prophets_051": ("İbrahim'in oğlu, babası ona kurban edilme rüyasını anlattığında nasıl tepki verdi?", ["Kabul etti: «Sana emredileni yap»", "Kaçtı", "Ağladı ve reddetti", "Saklandı"], "«Babacığım, sana emredileni yap» dedi. Allah onu büyük bir kurbanla fidye olarak kurtardı."),
"prophets_052": ("İbrahim duasında ailesinin bir kısmını nereye yerleştirdiğini söyler?", ["Kutsal Ev'in yanında ekinsiz bir vadiye", "Nil kıyısına", "Bir ormana", "Bir adaya"], "«Soyumdan bir kısmını Senin Kutsal Evin'in yanında ekinsiz bir vadiye yerleştirdim.»"),
"prophets_053": ("İbrahim duasında Mekke şehri için ne istedi?", ["Güvenli bir şehir olmasını ve halkına meyveler verilmesini", "Bir krallık olmasını", "Orada hep yağmur yağmasını", "Bir nehri olmasını"], "«Rabbim, burayı güvenli bir şehir kıl ve halkını meyvelerle rızıklandır.»"),
"prophets_054": ("Kâbe'yi yükseltirken İbrahim ile İsmail, Allah'tan soylarından ne göndermesini istediler?", ["Onlara ayetlerini okuyan, kendilerinden bir elçi", "Bir kral", "Bir ordu", "Bir hazine"], "«Rabbimiz, onlara kendi içlerinden Senin ayetlerini okuyacak bir elçi gönder.»"),
"prophets_055": ("Kur'an bir peygamberin tek başına «bir ümmet» olduğunu söyler. Hangisi?", ["İbrahim", "Nuh", "Musa", "Süleyman"], "«Şüphesiz İbrahim, Allah'a itaat eden, hakka yönelen bir ümmetti.»"),
"prophets_056": ("Kur'an Meryem suresinde İsmail'i hangi özelliğiyle över?", ["Sözüne sadıktı", "Çok zengindi", "Bir kraldı", "Yüzebiliyordu"], "«Şüphesiz o sözüne sadıktı; bir resul ve bir nebiydi.»"),
"prophets_057": ("Lut kavmine hangi ceza isabet etti?", ["Pişmiş çamurdan taş yağmuru", "Tufan", "Böcek sürüsü", "Kuraklık"], "«Şehrin altını üstüne getirdik ve üzerlerine pişmiş çamurdan taşlar yağdırdık.»"),
"prophets_058": ("Kur'an hangi iki peygamberin eşlerini inkârcılığa örnek verir?", ["Nuh ve Lut", "İbrahim ve Musa", "Davud ve Süleyman", "Eyyub ve Yunus"], "«Allah inkâr edenlere Nuh'un karısıyla Lut'un karısını örnek verir.»"),
"prophets_059": ("Yakub'un babası kimdi?", ["İshak", "İsmail", "İbrahim", "Yusuf"], "Melekler İbrahim'in eşine «İshak'ı, İshak'ın ardından da Yakub'u» müjdelediler."),
"prophets_060": ("Yusuf'a ağlamaktan Yakub'un gözlerine ne oldu?", ["Gözleri ağardı", "Geceleri daha iyi gördü", "Hiçbir şey değişmedi", "Bir gözünü kaybetti"], "«Üzüntüden gözleri ağardı, ama o kederini içine gömüyordu.»"),
"prophets_061": ("Yakub'un gözlerini ne açtı?", ["Yüzüne sürülen Yusuf'un gömleği", "Bir bitki", "Zemzem suyu", "Bir merhem"], "Yusuf dedi ki: «Bu gömleğimi götürün, babamın yüzüne sürün; gözleri açılacaktır.»"),
"prophets_062": ("Yusuf, haksız yere davet edildiği şeye boyun eğmek yerine neyi tercih etti?", ["Zindanı", "Sürgünü", "Serveti", "Sessizliği"], "«Rabbim, zindan bana bunların beni davet ettiği şeyden daha sevimlidir.»"),
"prophets_063": ("Zindanda iki genç Yusuf'a rüyalarını anlattı. Biri ne gördü?", ["Üzüm sıktığını", "Uçtuğunu", "Koyun güttüğünü", "Kuyu kazdığını"], "Biri şarap sıktığını, diğeri başında kuşların yediği ekmek taşıdığını gördü."),
"prophets_064": ("Yusuf hükümdara kaç yıl bolluk, sonra kaç yıl kuraklık haber verdi?", ["Yedi ve yedi", "Üç ve üç", "On ve on", "Bir ve bir"], "«Yedi yıl ekeceksiniz… sonra yedi zorlu yıl gelecek.»"),
"prophets_065": ("Yusuf Mısır hükümdarından hangi görevi istedi?", ["Ülkenin hazinelerini (ambarlarını)", "Ordu komutanlığını", "Tahtı", "Altın hazinesini"], "«Beni ülkenin hazinelerinin başına getir: ben iyi koruyan, bilen biriyim.»"),
"prophets_066": ("Yusuf, küçük kardeşini yanında tutmak için onun yüküne ne koydurdu?", ["Hükümdarın su kabını", "Bir kese altın", "Bir mektup", "Gömleğini"], "«Su kabını kardeşinin yüküne koydu.»"),
"prophets_067": ("Yakub oğullarına Mısır'a girmeden önce hangi öğüdü verdi?", ["Ayrı kapılardan girmelerini", "Gece yolculuk etmelerini", "Kılık değiştirmelerini", "Hediye götürmelerini"], "«Tek bir kapıdan girmeyin, ayrı ayrı kapılardan girin.»"),
"prophets_068": ("Yusuf'un kardeşleri, o Mısır'da yönetimdeyken neden Mısır'a geldiler?", ["Kıtlıkta erzak almak için", "Onu bulmak için", "Hac için", "Deve satmak için"], "Kardeşleri tahıl için geldiler; huzuruna girdiler ve onu tanımadılar."),
"prophets_069": ("Bebek Musa nehre bırakıldıktan sonra kimin evine alındı?", ["Firavun'un", "Bir çobanın", "Bir balıkçının", "Bir tüccarın"], "Firavun ailesi onu, bir gün kendilerine düşman ve tasa olsun diye aldı."),
"prophets_070": ("Bebek Musa sonunda annesine nasıl döndü?", ["Bütün sütanneleri reddetti ve kız kardeşi annesini önerdi", "Firavun acıyıp geri verdi", "Annesi geceleyin onu kaçırdı", "Bir melek taşıdı"], "Allah ona sütanneleri reddettirdi; kız kardeşi bir ev önerdi: annesinin eviydi, onu emzirdi."),
"prophets_071": ("Musa, görevinden önce Mısır'dan neden aceleyle ayrılmak zorunda kaldı?", ["Bir yumrukla kazara bir adamı öldürmüştü", "Saraydan çalmıştı", "Vergi vermeyi reddetmişti", "Firavun'a hakaret etmişti"], "Kavminden birine saldıran bir Mısırlıya vurdu ve onu öldürdü; hemen pişman oldu."),
"prophets_072": ("Musa'yı, ileri gelenlerin onu öldürmeyi planladığı konusunda kim uyardı?", ["Şehrin öbür ucundan koşarak gelen bir adam", "Annesi", "Harun", "Bir asker"], "«Şehrin öbür ucundan bir adam koşarak geldi: seni öldürmek için görüşüyorlar, hemen çık!»"),
"prophets_073": ("Musa Medyen'e vardığında su başındaki iki kadın için ne yaptı?", ["Sürülerini suladı", "Onlara deve sattı", "Onlara ev yaptı", "Onlara okuma öğretti"], "Sürülerini suladı, sonra gölgeye çekilip Allah'a yakardı."),
"prophets_074": ("Medyen'deki yaşlı adam, kızıyla evlenmesi için Musa'dan kaç yıl çalışmasını istedi?", ["Sekiz, isterse on", "Bir", "Kırk", "Üç"], "«Bana sekiz yıl çalışacaksın; on yılı tamamlarsan o senin lütfundur.»"),
"prophets_075": ("Allah Musa'ya kutsal Tuva vadisinde neyi çıkarmasını emretti?", ["Ayakkabılarını", "Cübbesini", "Asasını", "Sarığını"], "«Ayakkabılarını çıkar: sen kutsal Tuva vadisindesin.»"),
"prophets_076": ("Asadan sonra Musa'ya verilen ikinci mucize neydi?", ["Eli kusursuz, bembeyaz çıktı", "Uçabildi", "Sesi gök gürültüsü oldu", "Gece görebildi"], "«Elini koynuna sok: kusursuz, bembeyaz çıkacak.»"),
"prophets_077": ("Musa Firavun'a gitmeden önce Allah'tan ne istedi?", ["Göğsünü açmasını ve dilindeki düğümü çözmesini", "Bir ordu", "Altın", "Hızlı bir at"], "«Rabbim, göğsümü aç, işimi kolaylaştır, dilimdeki düğümü çöz.»"),
"prophets_078": ("Musa görevinde kendisine yardımcı olarak Allah'tan kimi istedi?", ["Kardeşi Harun'u", "Oğlunu", "Kayınpederini", "Bir meleği"], "«Bana ailemden bir yardımcı ver: kardeşim Harun'u.»"),
"prophets_079": ("Musa'nın asası sihirbazların göz boyamalarını yutunca Firavun'un sihirbazları ne yaptı?", ["Secdeye kapanıp iman ettiler", "Kaçtılar", "Güldüler", "Musa'ya saldırdılar"], "Sihirbazlar secdeye kapandılar: «Âlemlerin Rabbine, Musa ve Harun'un Rabbine iman ettik.»"),
"prophets_080": ("Kur'an, Firavun kavmine gönderilen belalar arasında şunlardan hangisini sayar?", ["Çekirge", "Kar", "Kurtlar", "Ateş"], "«Üzerlerine tufan, çekirge, haşere, kurbağa ve kan gönderdik.»"),
"prophets_081": ("Kur'an'a göre Allah, boğulduktan sonra Firavun'un bedenine ne yaptı?", ["İbret olsun diye korudu", "Yok etti", "Yaktı", "Kavmine geri verdi"], "«Bugün senden sonrakilere bir ibret olman için bedenini kurtaracağız.»"),
"prophets_082": ("Kur'an'a göre Firavun'un mümin eşi Allah'tan ne istedi?", ["Cennette, O'nun katında bir ev", "Bir oğul", "Firavun'un ölümünü", "Bir krallık"], "«Rabbim, bana katında cennette bir ev yap ve beni Firavun'dan kurtar.»"),
"prophets_083": ("Allah'ın Musa ile dağdaki buluşması kaç gece sürdü?", ["Kırk", "Yedi", "On", "Yüz"], "«Musa'ya otuz gece vaat ettik ve ona on gece daha ekledik: kırk gece.»"),
"prophets_084": ("Musa Allah'ı görmek isteyince ne oldu?", ["Allah dağa tecelli etti, dağ paramparça oldu ve Musa bayıldı", "Allah'ı gördü", "Hiçbir şey olmadı", "Dağ göğe yükseldi"], "«Dağa bak: yerinde durursa Beni göreceksin.» Dağ paramparça oldu ve Musa bayılıp düştü."),
"prophets_085": ("Allah Musa için öğütleri ve açıklamaları neyin üzerine yazdı?", ["Levhalara", "Hurma yapraklarına", "Siyah bir taşa", "Deriye"], "«Ona levhalarda her şeye dair öğüt yazdık.»"),
"prophets_086": ("Musa yokken İsrailoğullarının taptığı buzağıyı kim yaptı?", ["Sâmirî", "Harun", "Firavun", "Karun"], "«Sâmirî onları saptırdı»: ziynetlerinden böğüren bir buzağı heykeli yaptı."),
"prophets_087": ("Musa'nın asasıyla vurduğu kayadan kaç pınar fışkırdı?", ["On iki", "Yedi", "Üç", "Kırk"], "«Asanla kayaya vur»: her boy için bir tane, on iki pınar fışkırdı."),
"prophets_088": ("Allah çölde İsrailoğullarına hangi yiyeceği indirdi?", ["Kudret helvası ve bıldırcın", "Pirinç ve balık", "Hurma ve süt", "Ekmek ve zeytin"], "«Üzerinize kudret helvası ve bıldırcın indirdik.»"),
"prophets_089": ("Musa'nın İsrailoğullarına kesmelerini söylediği inek ne renkti?", ["Parlak sarı", "Siyah", "Beyaz", "Kırmızı"], "«Rengi parlak sarı, bakanların içini açan bir inek.»"),
"prophets_090": ("Musa'nın kavminden kim, kibri ve serveti yüzünden eviyle birlikte yerin dibine geçirildi?", ["Karun", "Hâmân", "Sâmirî", "Câlût"], "Karun büyük hazinelere sahipti; «onu da evini de yerin dibine geçirdik.»"),
"prophets_091": ("Allah Davud için hangi madeni yumuşattı?", ["Demiri", "Altını", "Bakırı", "Gümüşü"], "«Ona demiri yumuşattık.»"),
"prophets_092": ("Allah, insanları savaşta korumak için Davud'a neyin yapımını öğretti?", ["Zırh", "Kılıç", "Tahta kalkan", "Kule"], "«Sizi korumak için ona zırh yapmayı öğrettik.»"),
"prophets_093": ("Kur'an'a göre Davud savaşta hangi devi öldürdü?", ["Câlût'u", "Firavun'u", "Hâmân'ı", "Nemrut'u"], "«Davud Câlût'u öldürdü ve Allah ona hükümdarlık ve hikmet verdi.»"),
"prophets_094": ("Tâlût, Câlût'la karşılaşmadan önce ordusunu nasıl sınadı?", ["Bir nehirle: bir avuç dışında ondan içmemek", "Bir yarışla", "Üç günlük oruçla", "Tırmanılacak bir dağla"], "«Allah sizi bir nehirle sınayacak: ondan içen benden değildir, eliyle bir avuç alan hariç.»"),
"prophets_095": ("Allah, Davud ile birlikte kendisini tesbih etmek üzere neyi boyun eğdirdi?", ["Dağları ve kuşları", "Rüzgârları", "Cinleri", "Balıkları"], "«Dağları Davud'la birlikte tesbih etsinler diye boyun eğdirdik, kuşları da.»"),
"prophets_096": ("Allah, Süleyman'ı istediği yere taşıması için hangi unsuru emrine verdi?", ["Rüzgârı", "Ateşi", "Yağmuru", "Denizi"], "«Süleyman'a da emriyle mübarek toprağa doğru şiddetle esen rüzgârı verdik.»"),
"prophets_097": ("Süleyman'a Sebe krallığından haber getiren kuş hangisiydi?", ["Hüdhüd", "Kartal", "Güvercin", "Karga"], "Hüdhüd döndü ve dedi ki: «Senin bilmediğin bir şey öğrendim ve sana Sebe'den kesin bir haber getirdim.»"),
"prophets_098": ("Süleyman'ın ordusu yaklaşırken hangi küçük canlı türdeşlerini yuvalarına girmeleri için uyardı?", ["Bir karınca", "Bir arı", "Bir fare", "Bir örümcek"], "Bir karınca dedi ki: «Ey karıncalar, yuvalarınıza girin; Süleyman ve orduları farkında olmadan sizi ezmesin.»"),
"prophets_099": ("Sebe kraliçesinin tahtı Süleyman'a ne kadar çabuk getirildi?", ["Gözünü açıp kapamadan", "Bir günde", "Yedi günde", "Bir ayda"], "Kitaptan ilmi olan kişi dedi ki: «Gözünü açıp kapamadan onu sana getiririm.»"),
"prophets_100": ("Kur'an'a göre cinler Süleyman için ne yapıyordu?", ["Mabetler, heykeller ve büyük havuzlar", "Uçan halılar", "Gemiler", "Dağlar"], "«Ona dilediğini yapıyorlardı: mabetler, heykeller, havuz gibi çanaklar ve sabit kazanlar.»"),
"prophets_101": ("Cinler Süleyman'ın öldüğünü nasıl öğrendi?", ["Bir yer canlısı asasını kemirdi ve o yere düştü", "Bir melek söyledi", "Hüdhüd söyledi", "Öldüğünü gördüler"], "Ölümünü ancak asasını yiyen «yer canlısı» ortaya çıkardı; cinler gaybı bilmediklerini anladılar."),
"prophets_102": ("Süleyman Allah'a hangi özel duayı etti?", ["Kendisinden sonra kimseye nasip olmayacak bir hükümdarlık", "Uzun bir ömür", "Karun'un serveti", "Uçma gücü"], "«Rabbim, beni bağışla ve bana benden sonra kimseye nasip olmayacak bir hükümdarlık ver.»"),
"prophets_103": ("Allah Eyyub'a sağlığına kavuşması için ne emretti?", ["Ayağını yere vurmasını: serin bir pınar fışkırdı", "Bir ay oruç tutmasını", "Denizde yıkanmasını", "Bir dağa çıkmasını"], "«Ayağını yere vur: işte yıkanacak ve içecek serin bir su.»"),
"prophets_104": ("Yunus balığın karnının karanlığında hangi duayı etti?", ["«Senden başka ilah yoktur! Seni tenzih ederim, ben zalimlerden oldum»", "«Rabbim, bana bir krallık ver»", "«Rabbim, bana yağmur gönder»", "«Rabbim, Seni göreyim»"], "«Karanlıklar içinde seslendi: Senden başka ilah yoktur! Seni tenzih ederim; ben zalimlerden oldum.»"),
"prophets_105": ("Balık Yunus'u dışarı attıktan sonra Allah üzerine hangi bitkiyi bitirdi?", ["Bir kabak bitkisi (yaktîn)", "Bir hurma ağacı", "Bir zeytin ağacı", "Bir asma"], "«Üzerine kabak türünden bir bitki bitirdik.»"),
"prophets_106": ("Kur'an'a göre Yunus kaç kişiye gönderildi?", ["Yüz bin ya da daha fazla", "Bin", "On bin", "On iki"], "«Onu yüz bin ya da daha fazla kişiye gönderdik.»"),
"prophets_107": ("Allah, oğlunun geleceğini teyit etmek için Zekeriya'ya hangi işareti verdi?", ["Sağlıklı olduğu halde üç gece insanlarla konuşmamak", "Kayan bir yıldız", "Yazın yağmur", "Bir rüya"], "«Senin işaretin, sapasağlam olduğun halde üç gece insanlarla konuşamamandır.»"),
"prophets_108": ("Allah Yahya ismi hakkında ne söyler?", ["Daha önce kimseye bu isim verilmemişti", "Dedesinin adıydı", "Annesi seçti", "Bir kral adıydı"], "«Sana adı Yahya olan bir oğul müjdeliyoruz; daha önce kimseye bu adı vermedik.»"),
"prophets_109": ("Allah Yahya'ya henüz çocukken ne verdi?", ["Hikmet", "Bir krallık", "Bir at", "Bir hazine"], "«Ey Yahya, Kitab'a sımsıkı sarıl.» Ve ona çocukken hikmet verdik."),
"prophets_110": ("Meryem'in annesi karnındaki çocuk için ne adamıştı?", ["Onu Allah'ın hizmetine adamayı", "Onu Mısır'a göndermeyi", "Onu kral yapmayı", "Onu bir çobana emanet etmeyi"], "«Rabbim, karnımdakini Sana, Senin hizmetine adadım.»"),
"prophets_111": ("Meryem doğduktan sonra ona hangi peygamber bakmayı üstlendi?", ["Zekeriya", "Yahya", "İsa", "Davud"], "«Onu Zekeriya'nın himayesine verdi»; Zekeriya yanında Allah'tan rızık bulurdu."),
"prophets_112": ("Kur'an'a göre Allah Meryem'i kimlerin üzerine seçti?", ["Âlemlerin kadınlarının", "Kraliçelerin", "Meleklerin", "Peygamberlerin"], "«Ey Meryem, Allah seni seçti, tertemiz kıldı ve âlemlerin kadınları üzerine seçti.»"),
"prophets_113": ("Meryem hurma ağacının gövdesini silkelediğinde ne düştü?", ["Taze, olgun hurmalar", "Zeytin", "İncir", "Yağmur"], "«Hurma ağacının gövdesini kendine doğru silkele: üzerine taze, olgun hurmalar dökülsün.»"),
"prophets_114": ("Kur'an Mâide suresinde Meryem için hangi kelimeyi kullanır?", ["Sıddîka (dosdoğru)", "Kraliçe", "Peygamber kadın", "Savaşçı"], "«Meryem oğlu Mesih yalnızca bir elçidir… annesi de dosdoğru bir kadındı.»"),
"prophets_115": ("Kur'an Meryem oğlu İsa'ya hangi unvanı verir?", ["Mesih", "Halil", "Kelîm", "Sıddîk"], "«Adı Meryem oğlu İsa Mesih olacak; dünyada ve ahirette şerefli.»"),
"prophets_116": ("İsa, Allah'ın izniyle çamurdan ne şekillendirdi?", ["Canlanan bir kuş şekli", "Bir ev", "Bir kral heykeli", "Bir kayık"], "«Size çamurdan kuş şeklinde bir şey yapar, ona üflerim; Allah'ın izniyle kuş oluverir.»"),
"prophets_117": ("Kendilerini «Allah'ın yardımcıları» ilan eden İsa'nın yakın arkadaşlarına ne denir?", ["Havariler", "Ensar", "Muhacirler", "Sahabe"], "«Havariler dediler ki: biz Allah'ın yardımcılarıyız.»"),
"prophets_118": ("Havariler İsa'dan, Mâide suresine adını veren neyi istediler?", ["Gökten inen donatılmış bir sofra", "Bir kitap", "Bir krallık", "Altın"], "«Rabbin bize gökten bir sofra indirebilir mi?»"),
"prophets_119": ("Kur'an İsa'nın yeryüzündeki görevinin sonu hakkında ne söyler?", ["Ne öldürüldü ne çarmıha gerildi: Allah onu katına yükseltti", "Yaşlılıktan öldü", "Boğuldu", "Mısır'a gitti"], "«Onu öldürmediler, çarmıha da germediler… bilakis Allah onu katına yükseltti.»"),
"prophets_120": ("İsa kendisinden sonra gelecek bir elçiyi hangi isimle müjdeledi?", ["Ahmed", "Yahya", "Musa", "İlyas"], "«…benden sonra gelecek, adı Ahmed olan bir elçiyi müjdeleyici olarak.»"),
"prophets_121": ("İlyas peygamber kavmini hangi puta tapmakla kınadı?", ["Ba'l", "Hübel", "Lât", "Vedd"], "«Ba'l'e tapıp yaratıcıların en güzelini bırakıyor musunuz?»"),
"prophets_122": ("Kur'an hangi üç peygamberi birlikte «sabredenlerden» diye anar?", ["İsmail, İdris ve Zülkifl", "Nuh, Hud ve Salih", "Musa, Harun ve Yuşa", "Davud, Süleyman ve Eyyub"], "«İsmail, İdris ve Zülkifl: hepsi sabredenlerdendi.»"),
"prophets_123": ("Sâd suresinde İsmail ve Zülkifl ile birlikte hangi peygamberin adı geçer?", ["Elyesa", "Yunus", "Lut", "Şuayb"], "«İsmail'i, Elyesa'yı ve Zülkifl'i de an: hepsi hayırlılardandır.»"),
"prophets_124": ("Kur'an 33:40 ayetinde Peygamber Muhammed ﷺ'e hangi unvanı verir?", ["Peygamberlerin Sonuncusu (Hâtemü'n-Nebiyyîn)", "Arapların Kralı", "Müminlerin Babası", "Allah'ın Dostu"], "«Muhammed… Allah'ın Resulü ve peygamberlerin sonuncusudur.»"),
"prophets_125": ("Kur'an'a göre Peygamber Muhammed ﷺ ne olarak gönderildi?", ["Âlemlere rahmet olarak", "Kral olarak", "Yargıç olarak", "Savaşçı olarak"], "«Seni ancak âlemlere rahmet olarak gönderdik.»"),
"prophets_126": ("33:56 ayetine göre Allah ve melekleri Peygamber ﷺ için ne yapar?", ["Ona salât ederler", "Onu rüzgârlardan korurlar", "Ona yağmur gönderirler", "Onu sessizce izlerler"], "«Allah ve melekleri Peygamber'e salât ederler. Ey iman edenler, siz de ona salât edin ve selam verin!»"),
"prophets_127": ("Kur'an Kalem suresinde Peygamber ﷺ'in ahlakını nasıl niteler?", ["«Sen büyük bir ahlak üzeresin»", "«Sen büyük bir kralsın»", "«Sen en zenginsin»", "«Sen en güçlüsün»"], "«Şüphesiz sen büyük bir ahlak üzeresin.»"),
"prophets_128": ("3:144 ayeti Muhammed ﷺ hakkında neyi hatırlatır?", ["O yalnızca bir elçidir, ondan önce de elçiler gelip geçmiştir", "Asla ölmeyecektir", "O bir melektir", "Geleceği bilir"], "«Muhammed yalnızca bir elçidir; ondan önce de elçiler gelip geçmiştir.»"),
"prophets_129": ("33:7 ayeti ağır misak için hangi beş peygamberi birlikte anar?", ["Nuh, İbrahim, Musa, İsa ve Muhammed ﷺ", "Âdem, Nuh, Hud, Salih ve Lut", "Davud, Süleyman, Eyyub, Yunus ve İdris", "İsmail, İshak, Yakub, Yusuf ve Musa"], "«Peygamberlerden söz almıştık: senden, Nuh'tan, İbrahim'den, Musa'dan ve Meryem oğlu İsa'dan.»"),
"prophets_130": ("Buhârî'deki bir hadise göre her peygamber hangi işi yapmıştır?", ["Çobanlık", "Marangozluk", "Demircilik", "Tüccarlık"], "«Allah koyun gütmemiş hiçbir peygamber göndermemiştir»; Peygamber ﷺ de Mekkeliler için koyun gütmüştü."),
"prophets_131": ("Müslim'deki bir hadise göre hangi peygamber marangoz olarak çalıştı?", ["Zekeriya", "Nuh", "İdris", "Yusuf"], "Peygamber ﷺ dedi ki: «Zekeriya marangozdu.»"),
"prophets_132": ("Peygamber ﷺ hangi peygambere dünyada ve ahirette «insanların en yakını» olduğunu söyledi?", ["Meryem oğlu İsa'ya", "Musa'ya", "İbrahim'e", "Nuh'a"], "«Ben dünyada ve ahirette Meryem oğlu İsa'ya insanların en yakınıyım; peygamberler kardeştir.»"),
"prophets_133": ("Kur'an'ın kaç suresi bir peygamberin adını taşır?", ["Altı", "İki", "On iki", "Yirmi beş"], "Yunus (10), Hud (11), Yusuf (12), İbrahim (14), Muhammed (47) ve Nuh (71)."),
"prophets_134": ("Kur'an 11:75 ayetinde İbrahim'i hangi üç sözcükle niteler?", ["Yumuşak huylu, yufka yürekli, Allah'a yönelen", "Zengin, güçlü, bilgili", "Güçlü, hızlı, cesur", "Kral, yargıç, savaşçı"], "«Şüphesiz İbrahim yumuşak huylu, yufka yürekli ve Allah'a yönelen biriydi.»"),
"prophets_135": ("Şuayb, putperestliğin yanı sıra kavmini ne için kınadı?", ["Ölçü ve tartıda hile yapmak", "Namaz kılmamak", "Gece yolculuk etmek", "Balık yemek"], "«Ölçüyü ve tartıyı tam yapın, insanların mallarını eksik vermeyin.»"),
"prophets_136": ("Şuayb'ın kavmi mesajı reddettikten sonra onları ne yakaladı?", ["Bir deprem", "Bir tufan", "Ateş yağmuru", "Bir kuş sürüsü"], "«Derken onları deprem yakaladı ve yurtlarında diz üstü çökekaldılar.»"),
"prophets_137": ("Melekler İbrahim'in korkusunu yatıştırdıktan sonra ona hangi haberi verdiler?", ["Lut kavmine gönderildiklerini", "Bir tufan geleceğini", "Kâbe'nin yıkılacağını", "Firavun'un boğulacağını"], "«Korkma: biz Lut kavmine gönderildik.»"),
"prophets_138": ("İbrahim 14:40 ayetinde kendisi ve soyu için ne istedi?", ["Namazı dosdoğru kılanlardan olmayı", "Kral olmayı", "Zengin olmayı", "Uzun yaşamayı"], "«Rabbim, beni ve soyumdan gelenleri namazı dosdoğru kılanlardan eyle.»"),
"prophets_139": ("Yusuf kıssasının sonunda herkes ona secde etmeden önce kimi tahta çıkardı?", ["Anne babasını", "Kralı", "Kardeşlerini", "Oğlunu"], "«Anne babasını tahta çıkardı ve hepsi ona secdeye kapandılar»: çocukluk rüyası gerçekleşti."),
"prophets_140": ("Yusuf'un kardeşleri ondan neden kurtulmak istediler?", ["Kıskançlıktan: babaları onu daha çok seviyordu", "Hırsızlık yapmıştı", "Çalışmayı reddediyordu", "Hastaydı"], "«Yusuf ve kardeşi babamıza bizden daha sevgili… Yusuf'u öldürün ya da onu bir yere atın.»"),
"prophets_141": ("Yusuf'un kardeşleri, onu bir kurdun yediğine babalarını inandırmak için ne getirdiler?", ["Sahte kanla lekelenmiş gömleğini", "Ayakkabılarını", "Asasını", "Bir kurt dişi"], "«Gömleğini sahte bir kanla getirdiler»; Yakub «Güzel bir sabır» diye cevap verdi."),
"prophets_142": ("Allah, Musa'yı nehre bırakmasını ilham ederken annesine ne vaat etti?", ["Onu kendisine geri vermeyi ve elçi yapmayı", "Ona başka bir oğul vermeyi", "Onu kraliçe yapmayı", "Yağmur göndermeyi"], "«Korkma ve üzülme: onu sana geri vereceğiz ve onu elçilerden yapacağız.»"),
"prophets_143": ("Musa denizin yarılması için ona neyle vurdu?", ["Asasıyla", "Eliyle", "Bir taşla", "Kılıcıyla"], "«Asanla denize vur»: deniz yarıldı ve her parçası koca bir dağ gibi oldu."),
"prophets_144": ("Allah Musa'ya hitap ettiğinde ona söylediği ilk şey neydi?", ["«Ben Allah'ım, Benden başka ilah yoktur: Bana kulluk et ve namaz kıl»", "«Balık tutmaya git»", "«Bir gemi yap»", "«Firavun'a geri dön»"], "«Şüphesiz Ben Allah'ım; Benden başka ilah yoktur, Bana kulluk et ve Beni anmak için namaz kıl.»"),
"prophets_145": ("Allah, Musa ile Harun'a Firavun'la nasıl konuşmalarını söyledi?", ["Yumuşak sözle", "Öfkeyle", "Bağırarak", "Sessizce"], "«Firavun'a gidin… ona yumuşak söz söyleyin; belki öğüt alır veya korkar.»"),
"prophets_146": ("Musa, iki denizin birleştiği yere yolculuğunun başında genç yardımcısına ne söyledi?", ["İki denizin birleştiği yere varana kadar durmayacağını", "Eve dönmek istediğini", "Korktuğunu", "Altın aradığını"], "«İki denizin birleştiği yere varıncaya kadar durmayacağım, uzun zaman yürüsem bile.»"),
"prophets_147": ("İlim sahibi kul, Musa'nın önünde o anda anlayamadığı hangi işi yaptı?", ["Bir gemiyi deldi", "Bir köprü yaptı", "Bir ateş yaktı", "Bir ağaç dikti"], "Gemiyi deldi, sonra bir çocuğu öldürdü, sonra bir duvarı doğrulttu; ardından her birini Musa'ya açıkladı."),
"prophets_148": ("İsa'nın henüz beşikteyken söylediği ilk sözler neydi?", ["«Ben Allah'ın kuluyum; bana Kitab'ı verdi ve beni peygamber kıldı»", "«Ben Tanrı'nın oğluyum»", "«Ben bir kralım»", "«Açım»"], "«Dedi ki: ben Allah'ın kuluyum. Bana Kitab'ı verdi ve beni peygamber kıldı.»"),
"prophets_149": ("Âdem ile eşi ağaçtan yedikten sonra Allah'a ne dediler?", ["«Rabbimiz, kendimize zulmettik; bizi bağışlamazsan hüsrana uğrarız»", "«Bizim suçumuz değildi»", "«Ağacın suçuydu»", "Hiçbir şey demediler"], "«Rabbimiz, biz kendimize zulmettik; eğer bizi bağışlamaz ve bize acımazsan mutlaka hüsrana uğrayanlardan oluruz.»"),
"prophets_150": ("Nuh suresinin ilk ayetinde Allah Nuh'a kavmi için hangi görevi verdi?", ["Kendilerine acı bir azap gelmeden önce onları uyarmak", "Bir şehir kurmak", "Onlara balık tutmayı öğretmek", "Onları kral yapmak"], "«Nuh'u kavmine gönderdik: kendilerine acı bir azap gelmeden önce kavmini uyar.»"),
}
